import { renderProjects } from "./display-projects.js";
import { addTodoToProject, removeTodoId } from "./projectManager.js";

let todos = [];


class Todo{
    constructor(details){
        this.id = crypto.randomUUID();
        this.completed = false;
        this.project = details.project;
        this.title = details.title;
        this.description = details.description;
        this.dueDate = details.dueDate;
        this.priority = details.priority;
        this.notes = details.notes;
    }

}

const todoMethods =  {

    changeStatus(){
        this.completed  = ! this.completed;
        console.log(this);
    },

    updateProject(project){
        this.project = project;
    },

    updateTitle(title){
        this.title = title;
    },

    updateDescription(description){
        this.description = description;
    },

    updateDueDate(dueDate){
        this.dueDate = dueDate;
    },

    updatePriority(priority){
        this.priority = priority;
    },

    updateNotes(notes){
        this.notes = notes;
    },

}


function addTodo(todoDetails){
    downloadTodos();    
    console.log("adding todo",todoDetails);
    const todo = new Todo(todoDetails);
    todos.push(todo);
    uploadTodos();
    addTodoToProject(todoDetails.project, todo.id);
    addMethodsToTodo(todo);
    renderProjects(todo.project);
}

function updateTodo(todoId, todoDetails){
    const todo = getTodo(todoId);
    console.log(todo, todoDetails);
    if(todo.project !== todoDetails.project){
        removeTodoId(todo.project,todoId)
        addTodoToProject(todoDetails.project, todoId);
    }
    todo.updateProject(todoDetails.project);
    todo.updatePriority(todoDetails.priority);
    todo.updateTitle(todoDetails.title);
    todo.updateDescription(todoDetails.description);
    todo.updateDueDate(todoDetails.dueDate);
    todo.updateNotes(todoDetails.notes);

    uploadTodos();
    renderProjects(todo.project);
}

function changeStatus(todo){
    todo.changeStatus();
    uploadTodos();
}

function removeTodo(id){
    const index = todos.findIndex((todo)=>todo.id == id);
    todos.splice(index, 1);
    uploadTodos();
}

function getTodo(id){
    return todos.find((todo)=>todo.id === id);
}

function uploadTodos(){
    localStorage.setItem("todos", JSON.stringify(todos));
}

function downloadTodos(){
    if(localStorage.getItem("todos")!== null){
        todos = JSON.parse(localStorage.getItem("todos"));
        todos.forEach(todo=>addMethodsToTodo(todo));
    }
    else 
        todos = [];
}

function addMethodsToTodo(todo){
    Object.setPrototypeOf(todo, todoMethods)
}



export {addTodo, updateTodo, changeStatus, downloadTodos, getTodo, removeTodo};


