import { addTodo, getTodo, updateTodo } from "./todoManager.js";
import { getProjects } from "./projectManager.js";
import { format } from "date-fns";


const form = document.querySelector("#add-task-form");
const dialog = document.querySelector("#add-task-dialog");




function getDetails(){
    const projectInput = document.querySelector("#project");
    const priorityInput = document.querySelector("#priority")
    const titleInput = document.querySelector("#title");
    const descriptionInput = document.querySelector("#description");
    const dueDateInput = document.querySelector("#due-date");
    const notesInput = document.querySelector("#notes");

    const project = projectInput.selectedOptions[0].value;
    console.log(project);
    const priority = priorityInput.selectedOptions[0].value;
    const title = titleInput.value;
    const description = descriptionInput.value;
    const dueDate = dueDateInput.value;
    const notes = notesInput.value;
    dialog.close;
    return({project, priority, title, description, dueDate, notes});
}


function createAddForm(currentProjectId){

    const projectInput = document.querySelector("#project");
    projectInput.textContent = "";
    const projectOptions = getProjects();
    projectOptions.forEach(project=>{
        console.log(project);
        if(project.projectId === currentProjectId)
            projectInput.add(new Option(project.title, project.key,true, true));
        projectInput.add(new Option(project.title, project.key));
    });

    const dueDate = document.querySelector("#due-date");
    dueDate.min = format(new Date, "yyyy-mm-dd");

    const buttonContainer = document.querySelector("form div.button-container");
    buttonContainer.textContent = "";
    const button = document.createElement("button");
    button.textContent = "Add task";
    button.addEventListener("click",addHandler);
    buttonContainer.appendChild(button);


    function addHandler(e){
        e.preventDefault();
        if(form.checkValidity()){
            const todo = getDetails();
            form.reset();
            dialog.close();
            addTodo(todo);
        }
    }
}

function createEditForm(todoId){
    console.log("edit form");
    const todo = getTodo(todoId);

    const priority = document.querySelector("#priority");
    if(todo.priority == "high") priority.selectedIndex = 2;
    else if(todo.priority == "medium") priority.selectedIndex = 1
    else priority.selectedIndex = 0;


    const title = document.querySelector("#title");
    title.value = todo.title;
    
    const description = document.querySelector("#description");
    description.textContent = todo.description;

    const dueDate = document.querySelector("#due-date");
    dueDate.value = todo.dueDate;

    const notes = document.querySelector("#notes");
    notes.textContent = todo.notes;

    const buttonContainer = document.querySelector("form div.button-container");
    buttonContainer.textContent = "";
    const button = document.createElement("button");
    button.textContent = "Edit task";

    button.addEventListener("click", updateHandler);
    buttonContainer.appendChild(button);

    function updateHandler(e){
        e.preventDefault();
        if(form.checkValidity()){
            updateTodo(todoId, getDetails());
            dialog.close();
            form.reset();
        }
    }
}


export {createAddForm, createEditForm};